// The two instance IDs of a WPI object placed on a page (devdoc 2026102601 §3.4).
//   instance_id          <descriptor_id>_<version>_<seqno>, e.g. "input_4_1"; seqno is
//                        local to the page. Saved with the page.
//   dynamic_instance_id  generated by the frontend at run time and never saved.
// Both are attributes of the descriptor copy the page holds.
import type { JsonObject } from './types';

// The latest active version of each class, by kind and class ID, from
// GET /wpi/classes/versions: a class copy has no version attribute.
const versions = new Map<string, number>();

export function setClassVersions(byKind: Record<string, Record<string, number>>) {
	for (const [kind, classes] of Object.entries(byKind)) for (const [id, v] of Object.entries(classes)) versions.set(`${kind}:${id}`, v);
}

export function classVersion(kind: string, id: string): number | undefined {
	return versions.get(`${kind}:${id}`);
}

export function makeInstanceId(descriptorId: string, version: number | string, seqno: number): string {
	return `${descriptorId}_${version}_${seqno}`;
}

export function newDynamicInstanceId(): string {
	return globalThis.crypto?.randomUUID?.() ?? `dyn-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function seqnoOf(id: unknown): number {
	const n = typeof id === 'string' ? /_(\d+)$/.exec(id) : null;
	return n ? Number(n[1]) : 0;
}

function maxSeqno(value: unknown): number {
	if (Array.isArray(value)) return Math.max(0, ...value.map(maxSeqno));
	if (!value || typeof value !== 'object') return 0;
	return Math.max(0, ...Object.entries(value).map(([k, v]) => (k === 'instance_id' ? seqnoOf(v) : maxSeqno(v))));
}

// The next seqno of a page: one more than the greatest instance_id seqno found, at
// any depth, in the given descriptors (element, validator and action instances).
export function nextSeqno(instances: JsonObject[]): number {
	return maxSeqno(instances) + 1;
}

// The kind and class ID of a descriptor copy found in a page: an action or
// validator instance, or a page or element layouter (named by the attribute that
// holds it).
function copyOf(o: JsonObject, key: string): [string, string] | null {
	if (typeof o.action === 'string') return ['action', o.action];
	if (typeof o.validator === 'string') return ['validator', o.validator];
	if (typeof o.layouter === 'string' && key === 'page_layouter') return ['page-layouter', o.layouter];
	if (typeof o.layouter === 'string' && key === 'elem_layouter') return ['element-layouter', o.layouter];
	return null;
}

function stamp(v: unknown, key: string, assign: boolean, next: { n: number }): unknown {
	if (Array.isArray(v)) return v.map((x) => stamp(x, key, assign, next));
	if (!v || typeof v !== 'object') return v;
	const out: JsonObject = {};
	// A class copy and a panel's elements (the editor's nodes) are not walked.
	for (const [k, val] of Object.entries(v)) out[k] = k === 'class' || k === 'elem_list' ? (val as never) : (stamp(val, k, assign, next) as never);
	const copy = copyOf(out, key);
	if (copy) {
		if (!out.dynamic_instance_id) out.dynamic_instance_id = newDynamicInstanceId();
		const version = classVersion(copy[0], copy[1]);
		if (assign && !out.instance_id && version !== undefined) out.instance_id = makeInstanceId(copy[1], version, next.n++);
	}
	return out;
}

// The value with a dynamic_instance_id on every action, validator and layouter
// copy in it that has none, at any depth; existing ones are kept. With `taken`
// (the page's descriptors, whose seqnos are in use) a copy without an instance_id
// also gets one: that is when the editor has just placed it, saved or not.
// Without it, a stored page is only given its run-time IDs.
export function stampInstances<T>(value: T, taken: JsonObject[] | null): T {
	return stamp(value, '', taken !== null, { n: taken ? nextSeqno(taken) : 0 }) as T;
}

// The value without any dynamic_instance_id, at any depth, for saving.
export function stripDynamicIds<T>(value: T): T {
	return strip(value, ['dynamic_instance_id']) as T;
}

// The value without any instance_id or dynamic_instance_id, at any depth: a copy
// of a placed descriptor, which gets IDs of its own.
export function stripInstanceIds<T>(value: T): T {
	return strip(value, ['instance_id', 'dynamic_instance_id']) as T;
}

function strip(value: unknown, drop: string[]): unknown {
	if (Array.isArray(value)) return value.map((v) => strip(v, drop));
	if (!value || typeof value !== 'object') return value;
	const out: JsonObject = {};
	for (const [k, v] of Object.entries(value)) if (!drop.includes(k)) out[k] = k === 'class' ? (v as never) : (strip(v, drop) as never);
	return out;
}
